import { existsSync, readFileSync } from "node:fs";
import { join, normalize, relative } from "node:path";
import { AUTOGENERATED_DIR } from "../../constants.js";
import { formatCount } from "../../formatting.js";
import { declaresOwnDockerfile } from "../../native-service.js";
import { findProjectRoot } from "../../paths.js";
import { isWindows, powerShellPathLiteral } from "../../platform.js";
import { discoverResourcesFromRoot } from "../../services.js";
import { readJsonFile } from "./read-json.js";
function hasSyntheticDefaultImports(tsconfigPath) {
    const config = readJsonFile(tsconfigPath);
    const compilerOptions = config?.compilerOptions;
    return (compilerOptions?.allowSyntheticDefaultImports === true ||
        compilerOptions?.esModuleInterop === true);
}
export function checkFrontendDockerPreflight() {
    const projectRoot = findProjectRoot() ?? process.cwd();
    const frontends = discoverResourcesFromRoot(projectRoot).filter((resource) => resource.config?.appType === "frontend");
    // A frontend with its own Dockerfile owns the image build: Flisk does not generate
    // the frontend Dockerfile for it, so the generated build's `COPY public/` does not apply.
    const resources = frontends.filter((resource) => !declaresOwnDockerfile(resource.config));
    if (frontends.length === 0) {
        return {
            name: "Frontend Docker Preflight",
            didPass: true,
            isSkipped: true,
            message: "No frontend services to check",
        };
    }
    if (resources.length === 0) {
        return {
            name: "Frontend Docker Preflight",
            didPass: true,
            isSkipped: true,
            message: "All frontends build from their own Dockerfile",
        };
    }
    const problems = [];
    for (const resource of resources) {
        // The frontend Docker builder runs `COPY <resource>/public ./public`, so a missing
        // folder fails the image build with "/public: not found".
        if (!existsSync(join(resource.path, "public"))) {
            const publicDir = normalize(relative(projectRoot, join(resource.path, "public")));
            const gitkeep = normalize(relative(projectRoot, join(resource.path, "public", ".gitkeep")));
            const create = isWindows()
                ? `New-Item -ItemType Directory -Force ${powerShellPathLiteral(publicDir)}; ` +
                    `New-Item -ItemType File -Force ${powerShellPathLiteral(gitkeep)}`
                : `mkdir -p ${publicDir} && touch ${gitkeep}`;
            problems.push(`${resource.name}: no public/ folder, but the Docker build copies it. Create it: ${create}`);
        }
        const dockerfilePath = join(resource.path, AUTOGENERATED_DIR, "Dockerfile.app.autogenerated");
        const dockerTsconfigPath = join(resource.path, AUTOGENERATED_DIR, "tsconfig.docker.autogenerated.json");
        if (existsSync(dockerfilePath)) {
            const dockerfile = readFileSync(dockerfilePath, "utf-8");
            const exposesNginxPort = /\bEXPOSE\s+80\b/.test(dockerfile);
            const stack = resource.config?.stack;
            const composePath = stack
                ? join(projectRoot, "services", stack, AUTOGENERATED_DIR, "docker-compose.app.autogenerated.yml")
                : "";
            if (exposesNginxPort && composePath && existsSync(composePath)) {
                const compose = readFileSync(composePath, "utf-8");
                const escapedName = resource.name.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
                const portPattern = new RegExp(`traefik\\.http\\.services\\.${escapedName}\\.loadbalancer\\.server\\.port=(\\d+)`);
                const match = compose.match(portPattern);
                const routedPort = match?.[1];
                if (routedPort && routedPort !== "80") {
                    problems.push(`${resource.name}: nginx runtime exposes 80, but generated Traefik routes to ${routedPort}`);
                }
            }
        }
        if (existsSync(dockerTsconfigPath) && !hasSyntheticDefaultImports(dockerTsconfigPath)) {
            const mainPath = join(resource.path, "src", "main.tsx");
            if (existsSync(mainPath)) {
                const main = readFileSync(mainPath, "utf-8");
                const defaultImports = [
                    /import\s+\w+\s+from\s+["']react["']/,
                    /import\s+\w+\s+from\s+["']react-dom\/client["']/,
                ]
                    .filter((pattern) => pattern.test(main))
                    .map((pattern) => (pattern.source.includes("react-dom") ? "react-dom/client" : "react"));
                if (defaultImports.length > 0) {
                    problems.push(`${resource.name}: Docker tsconfig does not allow synthetic default imports, but src/main.tsx default-imports ${defaultImports.join(" and ")}`);
                }
            }
        }
    }
    if (problems.length === 0) {
        const frontendCount = formatCount(resources.length, "frontend");
        return {
            name: "Frontend Docker Preflight",
            didPass: true,
            message: `${frontendCount} ${resources.length === 1 ? "has" : "have"} compatible Docker build/routing metadata`,
        };
    }
    return {
        name: "Frontend Docker Preflight",
        didPass: false,
        message: `Frontend Docker metadata has issues that will make \`flisk up\` fail or route 404:\n    ${problems.join("\n    ")}`,
        fix: 'Regenerate with a current Flisk (`flisk config regenerate`) and ensure frontend nginx runtimes route to port 80. For React entrypoints, prefer named imports: `import { StrictMode } from "react"` and `import { createRoot } from "react-dom/client"`.',
    };
}
